void obd_can_ctrl_request(Obd_Can_Req_Enum request)
{
  obd_can_config ( request, OBD_CAN_ON_DEMAND, OBD_CAN_NO_EVENT, 0);
}

//--------------------------------------------------------------------------// 

Obd_Can_Req_Status obd_can_ctrl_request_status (Obd_Can_Req_Enum request)
{
  if (request >= OBD_CAN_REQ_COUNT)     return OBD_CAN_NOT_ENABLED;
  if (!obd_can_cfg[request].is_enabled) return OBD_CAN_NOT_ENABLED;  
  return obd_can_schedule[request].status;
}

//--------------------------------------------------------------------------// 

Boolean obd_can_is_req_enabled(Obd_Can_Req_Enum request)
{
  if (request <= OBD_CAN_REQ_COUNT)
  {
    return obd_can_cfg[request].is_enabled;
  }
  return FALSE;
}

